// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: an arbitrary amount of wei sent to receive (can be 0 or large).
    function testFuzz_property(uint256 amount) public {
        // keep domain wide: allow any amount up to full uint256 but bounded to contract-testable funds
        // give the caller enough balance to send `amount` (bound to a reasonable max to avoid out-of-gas in test harness)
        uint256 maxFund = 1 ether;
        if (amount > maxFund) amount = amount % (maxFund + 1);

        address actor = address(0xBEEF);
        vm.deal(actor, amount);

        // record previous depositsCount
        uint256 before = c.depositsCount();

        // make the call to receive via the actor
        vm.prank(actor);
        // call the receive by sending value; handle possible revert via try/catch on a low-level call
        bool ok;
        (ok,) = address(c).call{value: amount}("");

        // After the call, reference implementation guarantees that if the call succeeded,
        // depositsCount == before + 1. If call reverted, depositsCount unchanged.
        // We assert the universal property that either the call failed (ok==false) and
        // depositsCount == before, or the call succeeded (ok==true) and depositsCount == before + 1.
        // This single assertTrue reads the public getter depositsCount on c.
        uint256 after = c.depositsCount();
        assertTrue((ok == false && after == before) || (ok == true && after == before + 1));
    }
}

