pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an arbitrary sender address and an arbitrary amount
    function testFuzz_property(address sender, uint256 amount) public {
        // keep amounts within available bounds but wide: allow zero and large values
        vm.assume(sender != address(0)); // ensure a distinct sender (EOA)

        // Fund the sender so they can send 'amount' ether to c when needed
        // bound amount to a reasonable max to avoid out-of-gas in test harness
        uint256 bounded = amount % 1 ether; // still wide: [0, 1e18)
        vm.deal(sender, bounded);

        // record depositsCount before
        uint256 before = c.depositsCount();

        // perform receive by making a plain transfer: use prank to make the call from sender
        bool ok;
        vm.prank(sender);
        // low-level call to trigger receive with value; catch revert
        (bool success,) = address(c).call{value: bounded}("");
        ok = success;

        // After a successful receive call, correct contract increments depositsCount by exactly 1.
        // We assert that: if call succeeded then depositsCount == before + 1; if call reverted then obviously not
        // The universal property we assert is: whenever the call succeeds, depositsCount == before + 1
        // This will hold for the reference and be violated by the mutant for some inputs.
        if (ok) {
            uint256 after = c.depositsCount();
            assertTrue(after == before + 1);
        } else {
            // If the call reverted, still assert that the contract's depositsCount didn't change (revert -> no state change)
            // read current value and compare to before
            uint256 after = c.depositsCount();
            assertTrue(after == before);
        }
    }
}

