pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed amount and sender to let the fuzzer find inputs that cause the mutant to revert
    function testFuzz_property(uint256 amount, address sender) public {
        // keep amount within a wide but reasonable bound: up to 1e18 wei
        amount = bound(amount, 0, 1e18);
        // avoid the zero address as sender for clarity
        if (sender == address(0)) sender = address(1);

        // fund the sender so it can send ETH
        vm.deal(sender, amount);

        // read depositsCount before the call
        uint256 beforeCount = c.depositsCount();

        bool ok;
        // perform the payable send to trigger receive(); use low-level call by making the sender send Ether to c
        vm.prank(sender);
        (bool success, ) = address(c).call{value: amount}("");
        ok = success;

        uint256 afterCount = c.depositsCount();

        // The universal property to assert: if the receive call succeeded, depositsCount did not decrease
        // (i.e., afterCount >= beforeCount). This holds for the reference contract for all inputs,
        // and the mutant can cause a revert (so success==false) for some inputs; the test asserts the
        // general rule by checking only when the call succeeded.
        assertTrue(!ok || afterCount >= beforeCount);
    }
}

