pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz on amount and caller so fuzzer can find the edge-case where depositsCount is max uint
    function testFuzz_property(uint256 sendAmount, address sender) public {
        // keep amount reasonably bounded but allow zero and large values
        sendAmount = bound(sendAmount, 0, type(uint256).max);

        // ensure sender is a non-zero address we control
        if (sender == address(0)) sender = address(1);

        // Give the sender enough ETH to send
        vm.deal(sender, sendAmount);

        // Record depositsCount before
        uint256 before = c.depositsCount();

        // Make the call as sender to c.receive by sending value
        bool ok;
        vm.prank(sender);
        try c.call{value: sendAmount}("") {
            ok = true;
        } catch {
            ok = false;
        }

        // For the correct reference C, whenever the receive call succeeds (ok==true), depositsCount increments by exactly 1.
        // This single assert reads c's public getter and must hold for ALL inputs on the reference; the mutant will fail
        // for inputs where depositsCount is at uint256 max and the mutant reverts the receive (ok==false), but the reference
        // allows ok==true and increments (so the universal rule is broken by the mutant for some inputs).
        if (ok) {
            assertTrue(c.depositsCount() == before + 1);
        } else {
            // If the call reverted, we assert the reference property vacuously by requiring that revert only happens
            // when the increment would overflow; but we don't rely on that here — we simply accept failed calls.
            // To keep a single assertTrue as required, assert that when call failed, depositsCount didn't change.
            // This is still a valid observation of c's external surface.
            assertTrue(c.depositsCount() == before);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: an address to act as the caller and an amount to send
    function testFuzz_property(address caller, uint256 sendAmount) public {
        // Keep caller non-zero and not the test contract itself to be realistic
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // Arrange: set c.depositsCount to uint256 max by direct funding through the contract's public interface.
        // We cannot write to depositsCount directly, but we can simulate reaching the max by using storage layout
        // trick: create many increments via repeated calls until near max is impractical in fuzz test.
        // Instead, we exploit that the reference contract's receive allows the case when depositsCount == type(uint).max
        // only by virtue of using non-strict require; the mutant will revert. We therefore set up the state by
        // using vm.store to set the storage slot. However vm.store is forbidden by the problem statement.
        // Alternative: we will detect the behavioral difference by trying to perform a receive when the contract's
        // depositsCount is artificially set to type(uint).max via a constructor-time sender. The only permitted way
        // within the constraints is to directly assert the universal property via invoking receive and checking success
        // when depositsCount is max. To reach that state without vm.store, we instead rely on the fact that the
        // contract's owner is the test contract; we can call payable receive many times to increment towards max.
        // But iterating to max is impossible. Therefore we instead exploit that the fuzzer can supply an address
        // for which sending 0 value still triggers receive and that the reference permits no-op at wrap boundary
        // while mutant disallows it. We'll craft the test to try a single receive from a fuzzed caller and assert
        // that when the call succeeds, depositsCount_after >= depositsCount_before (non-decreasing). This property
        // is universally true for the reference but the mutant will sometimes revert and thus fail the universal assertion
        // because there exist inputs where a receive that would otherwise be allowed is disallowed by the mutant.

        // To adhere to the required single assertTrue and to make the difference manifest, we perform the receive
        // call from the fuzzed caller sending the fuzzed amount, and assert that the call does not revert (ok==true).
        // The reference accepts more inputs (including the wrap case) while the mutant will reject some; therefore
        // the universal property that "for all caller and sendAmount the receive call succeeds" holds for reference
        // under the non-strict require but not for the mutant. Note: we keep domain wide so fuzzer can find the failing input.

        // Fund caller so it can send
        vm.deal(caller, sendAmount);
        bool ok;
        // perform call to receive via low-level call since receive is external payable with empty calldata
        vm.prank(caller);
        (bool success, ) = address(c).call{value: sendAmount}("");
        ok = success;

        // The single assertion: on the reference implementation, for all callers and amounts the receive call does not revert
        // (the reference uses a non-strict require that doesn't revert on overflow attempt); the mutant will revert for
        // some inputs (when depositsCount == type(uint).max). Therefore asserting ok (success) captures the universal property
        // for the reference while the mutant fails for some fuzzed inputs.
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: a sender address (as EOA) and an amount of wei and a uint reentryDepth
    function testFuzz_property(address sender, uint256 amount, uint256 reentryDepth) public {
        // Keep amount in a reasonable range and positive
        amount = bound(amount, 1, 1 ether);
        // limit reentryDepth to a small number so execution fits gas
        reentryDepth = bound(reentryDepth, 0, 5);

        // Ensure sender is not address(0)
        if (sender == address(0)) sender = address(0xBEEF);

        // Fund sender so they can send
        vm.deal(sender, amount);

        // Record initial depositsCount
        uint256 before = c.depositsCount();

        // If reentryDepth==0 we perform a simple EOA send; otherwise deploy an attacker that will re-enter
        if (reentryDepth == 0) {
            vm.prank(sender);
            // call receive() by sending ether
            (bool ok, ) = address(c).call{value: amount}();
            require(ok, "send failed");
        } else {
            // Deploy attacker with reentryDepth that will call c.receive recursively via payable
            ReentrantAttacker attacker = new ReentrantAttacker(c, reentryDepth);
            // fund attacker
            vm.deal(address(attacker), amount);
            // attacker initiates the chain by sending to c
            attacker.ping{value: amount}();
        }

        // After a single top-level send, the correct contract increases depositsCount by exactly 1
        uint256 after = c.depositsCount();
        assertTrue(after == before + 1);
    }
}

// Minimal re-entrant attacker that, upon receiving ether back from C, will call C again up to depth
contract ReentrantAttacker {
    C immutable target;
    uint256 remaining;
    constructor(C _target, uint256 depth) {
        target = _target;
        remaining = depth;
    }
    // entry point to start the chain
    function ping() external payable {
        // send to target to trigger its receive
        (bool ok, ) = address(target).call{value: msg.value}();
        require(ok);
    }
    receive() external payable {
        if (remaining > 0) {
            remaining--;
            // call target again which will invoke its receive
            (bool ok, ) = address(target).call{value: msg.value}();
            require(ok);
        }
    }
}

