pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to send and number of reentrant nested calls the attacker will perform
    function testFuzz_property(uint128 amount, uint8 reentrancyDepth) public {
        // keep amount wide but nonzero and within contract balanceable bounds
        vm.assume(amount > 0);
        // limit reentrancyDepth to a reasonable bound so the test runs quickly but still fuzzes
        uint8 depth = reentrancyDepth % 5; // 0..4

        // Deploy attacker that will try to re-enter C's receive 'depth' times.
        ReentrantAttacker attacker = new ReentrantAttacker(c, depth);

        // Fund the attacker so it can send ETH to c
        vm.deal(address(attacker), amount);

        // Record depositsCount before the external send
        uint256 before = c.depositsCount();

        // Make the attacker perform an external call to C (attacker is a contract, but the external initiator
        // is considered the attacker contract here). We perform the call from the attacker itself.
        // The property we state concerns an EOA sending to C; to exercise the rule vs mutant we let the
        // attacker attempt reentrancy during the single external send.
        attacker.callReceive{value: amount}();

        // Exactly one assertion: for a single external send, the correct contract increments depositsCount by 1.
        // Read c via its public getter.
        uint256 after = c.depositsCount();
        assertTrue(after == before + 1);
    }
}

// Minimal adversarial helper: tries to re-enter C.receive() up to `depth` times during its receive()
contract ReentrantAttacker {
    C immutable target;
    uint8 immutable maxDepth;
    uint8 cur;

    constructor(C _target, uint8 _maxDepth) payable {
        target = _target;
        maxDepth = _maxDepth;
        cur = 0;
    }

    // entry called by the test to start the external send
    function callReceive() external payable {
        // send Ether to target; this triggers target.receive()
        (bool ok, ) = address(target).call{value: msg.value}("");
        // ignore return; we just want the side effects
        require(ok, "external send failed");
    }

    // receive will attempt to re-enter target.receive by performing low-level calls
    receive() external payable {
        if (cur < maxDepth) {
            cur++;
            // re-enter target.receive via low-level call with zero data
            // this simulates nested invocations during the same original external send
            // and is what can cause the mutant to increment multiple times
            (bool ok, ) = address(target).call{value: 0}("");
            // swallow the result to allow continuing
            ok;
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: amount to send, and number of reentrant calls attacker will make
    function testFuzz_property(uint256 amount, uint256 reentries) public {
        // keep amount within reasonable bounds and nonzero to actually trigger receive
        amount = bound(amount, 1, 1 ether);
        // bound reentries to a small number to keep test reasonable
        reentries = bound(reentries, 0, 5);

        // Deploy an attacker who will, when receiving Ether, optionally reenter C's receive `reentries` times
        ReentrantAttacker attacker = new ReentrantAttacker(c, uint32(reentries));

        // fund attacker so it can send Ether to C (we simulate an EOA funding a contract then having that contract send)
        vm.deal(address(attacker), amount);

        // Record depositsCount before the single external send from attacker (attacker acts like the caller)
        uint256 before = c.depositsCount();

        // The attacker will perform one external send to C in its triggerSend() call
        attacker.triggerSend{value: amount}();

        // After a single external send (from attacker), the correct contract C should have depositsCount == before + 1
        assertTrue(c.depositsCount() == before + 1);
    }
}

// Adversarial helper: on first receive it will reenter C.reentrant times by calling a bare send to C
contract ReentrantAttacker {
    C immutable c;
    uint32 public reentrant;
    uint32 public entered;

    constructor(C _c, uint32 _reentrant) payable {
        c = _c;
        reentrant = _reentrant;
        entered = 0;
    }

    // Called by test to initiate a single external send to C
    function triggerSend() external payable {
        // this single call will invoke this contract's receive, which does the reentrancy
        (bool ok, ) = address(c).call{value: msg.value}("");
        require(ok);
    }

    receive() external payable {
        // increment local counter
        entered++;
        // if still allowed, reenter C by making another low-level call with zero value (still a call to receive on C)
        // we perform reentrant calls until reentrant limit, each time sending 0 value so it's still nested within the original external send
        if (entered <= reentrant) {
            // reenter C -- this will invoke C.receive() again
            // use .call with empty calldata and 0 value to trigger receive
            (bool ok, ) = address(c).call{value: 0}("");
            require(ok);
        }
    }
}

