pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount sent and number of reentrant calls attacker will perform
    function testFuzz_property(uint128 amount, uint8 reentryDepth) public {
        // keep amount reasonable but allow zero and large values; wide admissible domain
        uint256 sendAmount = uint256(amount);
        // cap reentryDepth to a small max so test runtime is bounded but still fuzzed
        uint8 depth = reentryDepth % 5; // allow 0..4 reentries

        // Deploy attacker and fund it so it can send Ether
        ReentrantAttacker attacker = new ReentrantAttacker(address(c), depth);
        vm.deal(address(attacker), sendAmount);

        // record depositsCount before
        uint256 before = c.depositsCount();

        // make the attacker perform a single external transfer to c (attacker's receive will re-enter depth times)
        attacker.attack{value: sendAmount}();

        // After one external transfer (from attacker as an external contract), the reference contract
        // guarantees depositsCount increased by exactly 1. The mutant that unconditionally increments
        // (and is vulnerable to reentrancy effects) can end up incrementing it more than once.
        uint256 after = c.depositsCount();

        assertTrue(after == before + 1);
    }
}

// Minimal re-entrant attacker: sends Ether to C once (as an external call), and on receiving
// Ether will re-enter by calling payable address(c).call("") up to `depth` times.
contract ReentrantAttacker {
    address payable public target;
    uint8 public remaining;

    constructor(address _target, uint8 _depth) payable {
        target = payable(_target);
        remaining = _depth;
    }

    // entrypoint to start attack: perform an external send to target so target.receive() executes
    function attack() external payable {
        // send Ether to target as a plain transfer-like call so target.receive() runs
        (bool ok, ) = target.call{value: msg.value}("");
        require(ok);
    }

    // on receiving funds, optionally re-enter target by doing another plain call
    receive() external payable {
        if (remaining > 0) {
            remaining -= 1;
            // re-enter target.receive()
            (bool ok, ) = target.call{value: 0}("");
            require(ok);
        }
    }
}

