contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount of wei to send and a reentry depth the attacker will attempt
    function testFuzz_property(uint256 amount, uint256 reentryDepth) public {
        // keep amount admissible and nonzero (sending zero still calls receive but we keep wide domain)
        vm.assume(amount <= address(this).balance + 1e30); // wide bound, harmless
        // bound reentryDepth so test runs reasonably but still fuzzed
        uint256 depth = bound(reentryDepth, 0, 5);

        // deploy attacker that will re-enter C's receive up to `depth` times
        ReentrantAttacker attacker = new ReentrantAttacker(address(c), depth);

        // fund attacker so it can send ether to C
        vm.deal(address(attacker), amount);

        // record depositsCount before the single external send from attacker
        uint256 before = c.depositsCount();

        // make attacker perform a single external send to C (this will trigger receive and possible reentries)
        attacker.attack{value: amount}();

        // read depositsCount after the operation
        uint256 after = c.depositsCount();

        // general rule: for any single external EOA-initiated plain send, depositsCount increases by exactly 1
        // we assert that after == before + 1. This holds for the reference implementation for all inputs.
        // The mutant (which unconditionally increments) can be forced via reentrancy to increment more than once
        // during what appears as one external send; the fuzzer can find such a depth to break the mutant.
        assertTrue(after == before + 1);
    }
}

// Minimal re-entrant attacker: on receive it will, while remaining within the single external call from its perspective,
// call C.receive by sending ether back to C. We perform at most `maxReenter` nested reentries.
contract ReentrantAttacker {
    address payable public target;
    uint256 public maxReenter;
    uint256 public entered;

    constructor(address _target, uint256 _maxReenter) payable {
        target = payable(_target);
        maxReenter = _maxReenter;
        entered = 0;
    }

    // single external entry point invoked by the test; it simply sends its entire balance to target
    function attack() external payable {
        // send to target; this will trigger target.receive()
        (bool ok, ) = target.call{value: msg.value}("");
        // ignore ok; behavior observed via depositsCount getter in test
        entered = 0;
    }

    // on receiving ether from the test, this fallback will try to re-enter target up to maxReenter times
    receive() external payable {
        if (entered < maxReenter) {
            entered++;
            // re-enter target.receive by sending 0 wei; still counts as an external call
            // use call with value 0 to re-enter via its receive
            (bool s, ) = target.call{value: 0}("");
            // ignore success; test observes state change
        }
    }
}

