import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz the sender address and the amount to send. The property:
    // For any sender and any positive amount of wei, calling receive() with that
    // value should succeed on the correct contract (i.e., not revert). The mutant
    // rejects some such sends (it reverts when depositsCount would become >=1).
    function testFuzz_property(address sender, uint256 amount) public {
        // keep amount in a wide, sensible domain: allow zero or positive amounts but
        // we focus on positive transfers (amount > 0) since receive with 0 value is
        // also a valid operation but the mutant blocks the first positive deposit.
        // Bound amount to a reasonable max to avoid out-of-gas scenarios in the fuzzer.
        amount = bound(amount, 0, 1 ether);

        // Ensure sender has funds to send if amount > 0
        if (amount > 0) {
            vm.deal(sender, amount);
        }

        // Try to perform a payable low-level send to trigger receive(). We must
        // observe whether the call succeeds (ok == true) or reverts (ok == false).
        bool ok;
        // If sender is the zero address, vm.prank will still work; no assumption
        // to exclude EOAs — keep domain wide so fuzzer can find failing case.
        vm.startPrank(sender);
        // perform a call that sends value to the contract to invoke receive()
        try c.call{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // Single assertion: on the correct contract the receive should never revert
        // for any sender and any nonzero amount. This is the universal property.
        // The mutant will cause ok == false for some (sender, amount) (e.g. first
        // positive deposit) causing the assertion to fail.
        // We assert true for both amount==0 and amount>0 because the reference
        // receive only has a monotonicity check that always holds in uint arithmetic
        // and therefore never reverts; thus ok must be true for all amounts.
        assertTrue(ok);
    }
}

