contract OwnerReceiver {
    event Received(address from, uint256 amount);

    // deploy a new C with this contract as deployer/owner
    function deployC() external payable returns (C) {
        C instance = new C();
        // forward the received value to the instance
        if (msg.value > 0) {
            (bool s,) = address(instance).call{value: msg.value}("");
            require(s);
        }
        return instance;
    }

    // call withdraw on a C instance
    function callWithdraw(C c, uint256 amt) external {
        c.withdraw{ }(amt);
    }

    // receive function to accept ETH
    receive() external payable {
        emit Received(msg.sender, msg.value);
    }
}

